  1→import { useState } from "react";
  2→import { Card, CardContent, CardHeader } from "@/components/ui/card";
  3→import { Badge } from "@/components/ui/badge";
  4→import { ChevronDown, ChevronUp } from "lucide-react";
  5→
  6→interface Role {
  7→  title?: string;
  8→  company?: string;
  9→  start?: string;
 10→  end?: string;
 11→  description?: string;
 12→  type?: string;
 13→  employment_type?: string;
 14→}
 15→
 16→interface ExperiencePanelProps {
 17→  parsedJson: any;
 18→  matchedMustHaves?: string[];
 19→}
 20→
 21→const parseDate = (dateStr?: any): Date | null => {
 22→  if (dateStr == null) return null;
 23→  const s = String(dateStr).trim();
 24→  if (/present|current|now/i.test(s)) return new Date();
 25→  const monthNames: Record<string, number> = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11 };
 26→  const mmmYyyy = s.match(/([a-zA-Z]+)\s*(\d{4})/);
 27→  if (mmmYyyy) { const mo = monthNames[mmmYyyy[1].slice(0, 3).toLowerCase()]; if (mo !== undefined) return new Date(parseInt(mmmYyyy[2]), mo); }
 28→  const numDate = s.match(/(\d{1,2})[\/\-](\d{4})/);
 29→  if (numDate) return new Date(parseInt(numDate[2]), parseInt(numDate[1]) - 1);
 30→  const yearOnly = s.match(/\b(19|20)\d{2}\b/);
 31→  if (yearOnly) return new Date(parseInt(yearOnly[0]), 0);
 32→  return null;
 33→};
 34→
 35→const isCurrent = (dateStr?: any): boolean => dateStr != null && /present|current|now/i.test(String(dateStr));
 36→
 37→const monthsBetween = (start: Date, end: Date): number =>
 38→  Math.max(0, (end.getFullYear() - start.getFullYear()) * 12 + (end.getMonth() - start.getMonth()));
 39→
 40→const formatDuration = (months: number): string => {
 41→  if (months <= 0) return "";
 42→  const yrs = Math.floor(months / 12);
 43→  const mos = months % 12;
 44→  if (yrs === 0) return `${mos} mos`;
 45→  if (mos === 0) return `${yrs} yr${yrs !== 1 ? "s" : ""}`;
 46→  return `${yrs} yr${yrs !== 1 ? "s" : ""} ${mos} mos`;
 47→};
 48→
 49→const formatDate = (d: Date): string => {
 50→  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
 51→  return `${months[d.getMonth()]} ${d.getFullYear()}`;
 52→};
 53→
 54→const getEmpLabel = (role: Role): string => {
 55→  const t = (role.employment_type || role.type || "").toLowerCase();
 56→  if (t.includes("intern")) return "Internship";
 57→  if (t.includes("contract") || t.includes("freelance")) return "Contract";
 58→  if (t.includes("part")) return "Part-time";
 59→  return "Full-time";
 60→};
 61→
 62→const ExperiencePanel = ({ parsedJson, matchedMustHaves }: ExperiencePanelProps) => {
 63→  const [showAll, setShowAll] = useState(false);
 64→  const rawRoles = parsedJson?.roles_with_dates ?? parsedJson?.experience;
 65→  const roles: Role[] = Array.isArray(rawRoles) ? rawRoles : [];
 66→  const matchedLower = Array.isArray(matchedMustHaves) ? matchedMustHaves.map((m) => String(m).toLowerCase()) : [];
 67→
 68→  const parsed = roles.map((role) => {
 69→    const startDate = parseDate(role.start);
 70→    const endDate = parseDate(role.end) || (isCurrent(role.end) ? new Date() : null);
 71→    const months = startDate && endDate ? monthsBetween(startDate, endDate) : 0;
 72→    const empLabel = getEmpLabel(role);
 73→    const isCurrentRole = isCurrent(role.end);
 74→    const combined = `${role.title || ""} ${role.description || ""} ${role.company || ""}`.toLowerCase();
 75→    const isRelevant = matchedLower.some((m) => {
 76→      const words = m.split(/\s+/).filter((w) => w.length > 3);
 77→      return words.some((w) => combined.includes(w));
 78→    });
 79→    return { ...role, startDate, endDate, months, empLabel, isCurrentRole, isRelevant };
 80→  });
 81→
 82→  const totalMonths = parsed.reduce((sum, r) => sum + r.months, 0);
 83→
 84→  return (
 85→    <Card>
 86→      <CardHeader className="pb-3 px-4 pt-4 flex-row items-center gap-2 space-y-0">
 87→        <h4 className="text-sm font-medium text-foreground">Experience</h4>
 88→        {totalMonths > 0 && <Badge variant="secondary" className="text-[11px] h-5">{formatDuration(totalMonths)}</Badge>}
 89→        <Badge variant="secondary" className="text-[11px] h-5">{parsed.length}</Badge>
 90→      </CardHeader>
 91→      <CardContent className="px-4 pb-4 pt-0 space-y-3">
 92→        {parsed.length > 0 ? (
 93→          <>
 94→            <div className="space-y-3">
 95→              {parsed.slice(0, showAll ? undefined : 3).map((role, i) => (
 96→                <div key={i} className="flex gap-3">
 97→                  <div className="flex flex-col items-center pt-1.5 shrink-0">
 98→                    <div className={`w-1.5 h-1.5 rounded-full ${role.isRelevant ? "bg-primary" : "bg-muted-foreground/40"}`} />
 99→                    {i < Math.min(parsed.length, showAll ? parsed.length : 3) - 1 && (
100→                      <div className="w-px flex-1 bg-border mt-1" />
101→                    )}
102→                  </div>
103→                  <div className="flex-1 min-w-0 pb-1">
104→                    <div className="flex items-center gap-1.5 flex-wrap">
105→                      <span className="text-sm font-medium text-foreground">{role.title || "Untitled Role"}</span>
106→                      <Badge variant="outline" className="text-[10px] h-4">{role.empLabel}</Badge>
