 12→const getRecommendation = (score: number, hardFit: boolean | undefined, isHeuristic: boolean): { text: string; label: string; variant: RecLevel } => {
 13→  if (isHeuristic) return { text: "Needs full AI scoring for reliable recommendation", label: "Pending", variant: "warning" };
 14→  if (score >= 70 && hardFit !== false) return { text: "Strong core fit, gaps are learnable", label: "Shortlist", variant: "success" };
 15→  if (score >= 50 && hardFit !== false) return { text: "Decent match, review before interview", label: "Consider", variant: "secondary" };
 16→  if (score >= 40) return { text: "Has strengths but missing critical items", label: "Review", variant: "warning" };
 17→  return { text: "Significant gaps for this role", label: "Pass", variant: "destructive" };
 18→};
